std::string labels(juce::Component& c){std::string s;for(auto* x:c.getChildren())if(auto* l=dynamic_cast<juce::Label*>(x);l&&l->isVisible())s+=l->getText().toStdString()+"\n";return s;}
std::string sourceIdentity(const lesson::Admission& admission){
 const auto& identity=admission.identity().object();std::string text=identity.at("item_id").string()+" / "+identity.at("variant_id").string()+" | Source: ";
 for(std::size_t i=0;i<admission.model()->source().sourceRefs.size();++i){if(i)text+=", ";text+=admission.model()->source().sourceRefs[i];}
 return text+" | Content: "+identity.at("content_version").string()
     +" | Revision: "+storage::canonical(identity.at("content_revision"));
}
// Direct Practice/status fixture: the catalog is explicitly loaded, not Home's installed hierarchy loader.
void directSourceLoad(Harness& h,const std::filesystem::path& bundle){
 h.wait([&]{return desktop::LearnNavigationTestAccess::originalDiscoverySettled(*h.home);},"original synthetic profile suite discovery settled");
 if(!A::lessons(*h.home).load(bundle)||!A::lessons(*h.home).catalogReady())throw std::runtime_error("Exact direct representative catalog must be ready");
 if(!h.home->navigate(H::Page::Learn)||!A::lessons(*h.home).catalogReady())throw std::runtime_error("Direct admitted Learn fixture entry must preserve catalog readiness");
}
